"""Correct rewrite: exp(x - logsumexp(x)), the log-domain form, accumulated in float64."""
import numpy as np


def softmax(x: np.ndarray) -> np.ndarray:
    wide = np.asarray(x, dtype=np.float64)
    m = np.max(wide, axis=-1, keepdims=True)
    lse = m + np.log(np.sum(np.exp(wide - m), axis=-1, keepdims=True))
    return np.exp(wide - lse).astype(x.dtype)

