"""Correct rewrite: single-pass 'online' normalizer (Milakov & Gimelshein 2018) over chunks of
4 columns, keeping a running max and a rescaled running sum, all in float32."""
import numpy as np

CHUNK = 4


def softmax(x: np.ndarray) -> np.ndarray:
    z = np.asarray(x, dtype=np.float32)
    rows = z.shape[:-1]
    m = np.full(rows + (1,), -np.inf, dtype=np.float32)
    s = np.zeros(rows + (1,), dtype=np.float32)
    for start in range(0, z.shape[-1], CHUNK):
        blk = z[..., start : start + CHUNK]
        m_new = np.maximum(m, np.max(blk, axis=-1, keepdims=True))
        s = s * np.exp(m - m_new) + np.sum(np.exp(blk - m_new), axis=-1, keepdims=True)
        m = m_new
    return (np.exp(z - m) / s).astype(x.dtype)

