"""Correct rewrite: multiply by the reciprocal of the row sum instead of dividing; float32."""
import numpy as np


def softmax(x: np.ndarray) -> np.ndarray:
    z = np.asarray(x, dtype=np.float32)
    z = z - np.max(z, axis=-1, keepdims=True)
    e = np.exp(z)
    inv = np.float32(1.0) / np.sum(e, axis=-1, keepdims=True)
    return (e * inv).astype(x.dtype)

=== correct_variants/sequential_f32_accumulate.py ===
"""Correct rewrite: strictly sequential float32 accumulation of the row sum (worst-case
rounding growth, linear in n rather than log2 n)."""
import numpy as np


def softmax(x: np.ndarray) -> np.ndarray:
    z = np.asarray(x, dtype=np.float32)
    z = z - np.max(z, axis=-1, keepdims=True)
    e = np.exp(z)
    s = np.zeros(e.shape[:-1] + (1,), dtype=np.float32)
    for j in range(e.shape[-1]):
        s = s + e[..., j : j + 1]  # one float32 rounding per step, left to right
    return (e / s).astype(x.dtype)

